import urllib.request
base='https://raw.githubusercontent.com/yaringal/DropoutUncertaintyExps/a6259f1db8f5d3e2d743f88ecbde425a07b12445/'
for f in ['net/net.py','experiment.py']:
    try:
        t=urllib.request.urlopen(base+f,timeout=30).read().decode()
        open('repo/old_'+f.replace('/','_'),'w').write(t)
        print('=== ',f,len(t))
    except Exception as e:
        print('FAIL',f,e)

import urllib.request,json
for url in ['https://api.github.com/repos/yaringal/DropoutUncertaintyExps/git/trees/a6259f1db8f5d3e2d743f88ecbde425a07b12445?recursive=1']:
    try:
        d=json.load(urllib.request.urlopen(url,timeout=30))
        for t in d.get('tree',[]):
            if t['path'].endswith('.py') or 'spearmint' in t['path'].lower(): print(t['path'])
    except Exception as e: print('FAIL',e)
